import re, glob

def strip_comments(text):
    def repl_block(m):
        return '\n' * m.group(0).count('\n')
    text = re.sub(r'/-.*?-/', repl_block, text, flags=re.DOTALL)
    text = re.sub(r'--.*', '', text)
    return text

files = glob.glob('AlgebraicJacobian/**/*.lean', recursive=True)
total_plain = 0
total_et = 0
plain_files = {}
et_files = {}
for fn in files:
    with open(fn, encoding='utf-8') as f:
        raw = f.read()
    stripped = strip_comments(raw)
    et = re.findall(r'\[\s*(?:[A-Za-z0-9_]+\.)?HasPicSchemeEt\b', stripped)
    plain = re.findall(r'\[\s*(?:[A-Za-z0-9_]+\.)?HasPicScheme\b(?!Et)', stripped)
    if et:
        et_files[fn] = len(et); total_et += len(et)
    if plain:
        plain_files[fn] = len(plain); total_plain += len(plain)

print("PLAIN total:", total_plain, "files:", len(plain_files))
for k,v in sorted(plain_files.items()): print(" ", k, v)
print()
print("ET total:", total_et, "files:", len(et_files))
for k,v in sorted(et_files.items()): print(" ", k, v)
